73	int main(int argc,char**argv){
74	    int w=argc>1?std::atoi(argv[1]):4096,h=argc>2?std::atoi(argv[2]):2048,seed=argc>3?std::atoi(argv[3]):13;
75	    bool audit=argc>4&&std::strcmp(argv[4],"--audit")==0;
76	    if(w<1||h<1||w>8192||h>8192)return 2;
77	    return audit?run_audit(w,h,seed):run_fast(w,h,seed);
78	}

